const redactAuditTouching = `-- name: RedactAuditTouching :exec
UPDATE audit_revisions SET prior_values = NULL
WHERE workspace_id = $1
  AND (aggregate_id = ANY($2::uuid[])
       OR EXISTS (
         SELECT 1 FROM unnest($3::text[]) AS ref
         WHERE prior_values IS NOT NULL AND strpos(prior_values::text, ref) > 0
       ))
`

type RedactAuditTouchingParams struct {
	WorkspaceID  pgtype.UUID
	AggregateIds []pgtype.UUID
	Refs         []string
}

// redact prior content for the purged aggregate and any audit row whose
// bounded prior values mention a purged id; actor/action/timestamp/
// aggregate id/revision stay (03 deletion matrix).
func (q *Queries) RedactAuditTouching(ctx context.Context, arg RedactAuditTouchingParams) error {
	_, err := q.db.Exec(ctx, redactAuditTouching, arg.WorkspaceID, arg.AggregateIds, arg.Refs)
	return err
}

const setMaintenanceFlag = `-- name: SetMaintenanceFlag :one
UPDATE system_state SET maintenance = $1, updated_at = now()
WHERE id = true
RETURNING maintenance
`

func (q *Queries) SetMaintenanceFlag(ctx context.Context, maintenance bool) (bool, error) {
	row := q.db.QueryRow(ctx, setMaintenanceFlag, maintenance)
	var maintenance_2 bool
	err := row.Scan(&maintenance_2)
	return maintenance_2, err
}

const startExportJob = `-- name: StartExportJob :one
UPDATE export_jobs SET state = 'RUNNING'
WHERE id = $1 AND workspace_id = $2 AND state = 'QUEUED'
RETURNING id, workspace_id, state, snapshot_at, manifest_sha256, error_code, created_at, finished_at, expires_at, agent_grant_id, agent_credential_id
`

type StartExportJobParams struct {
	ID          pgtype.UUID
	WorkspaceID pgtype.UUID
}

func (q *Queries) StartExportJob(ctx context.Context, arg StartExportJobParams) (ExportJob, error) {
	row := q.db.QueryRow(ctx, startExportJob, arg.ID, arg.WorkspaceID)
	var i ExportJob
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.State,
		&i.SnapshotAt,
		&i.ManifestSha256,
		&i.ErrorCode,
		&i.CreatedAt,
		&i.FinishedAt,
		&i.ExpiresAt,
		&i.AgentGrantID,
		&i.AgentCredentialID,
	)
	return i, err
}

const tombstoneReceiptsTouching = `-- name: TombstoneReceiptsTouching :exec
UPDATE mutation_receipts SET gone = true, result = '{"gone": true}'::jsonb
WHERE workspace_id = $1 AND NOT gone AND operation <> 'purgePlant'
  AND EXISTS (
    SELECT 1 FROM unnest($2::text[]) AS ref
    WHERE strpos(result::text, ref) > 0
  )
`

type TombstoneReceiptsTouchingParams struct {
	WorkspaceID pgtype.UUID
	Refs        []string
}

// stored responses that reference any purged id replay as RESOURCE_GONE;
// operation/key/hash stay until their original TTL. The purge command's
// own receipt replays its minimal success instead.
func (q *Queries) TombstoneReceiptsTouching(ctx context.Context, arg TombstoneReceiptsTouchingParams) error {
	_, err := q.db.Exec(ctx, tombstoneReceiptsTouching, arg.WorkspaceID, arg.Refs)
	return err
}
